// Package: Azure.AI.Search
// Demonstrates hybrid retrieval with metadata filtering using Azure AI Search.

using Azure;
using Azure.AI.Search;
using Azure.AI.Search.Models;

public sealed class HybridRetriever
{
    private readonly SearchClient _searchClient;
    private readonly IEmbeddingGenerator<string, Embedding<float>> _embedder;

    public HybridRetriever(
        SearchClient searchClient,
        IEmbeddingGenerator<string, Embedding<float>> embedder)
    {
        _searchClient = searchClient ?? throw new ArgumentNullException(nameof(searchClient));
        _embedder = embedder ?? throw new ArgumentNullException(nameof(embedder));
    }

    public async Task<IReadOnlyList<SearchResult>> SearchWithFilterAsync(
        string query,
        string? tenantId,
        string? category,
        CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(query);

        var queryResult = await _embedder.GenerateAsync(query, ct);
        var vector = queryResult.Vector.ToArray();

        var options = new SearchOptions
        {
            Size = 8,
            VectorSearch = new VectorSearchOptions
            {
                Queries = { new VectorizedQuery(vector) { KNearestNeighborsCount = 8 } }
            }
        };

        if (!string.IsNullOrEmpty(tenantId))
        {
            options.Filter = $"(tenantId eq '{tenantId}')";
        }

        if (!string.IsNullOrEmpty(category))
        {
            options.Filter = string.IsNullOrEmpty(options.Filter)
                ? $"(category eq '{category}')"
                : $"{options.Filter} and (category eq '{category}')";
        }

        var response = await _searchClient.SearchAsync<DocumentChunkProjection>(
            "*",
            options,
            ct);

        var results = new List<SearchResult>();
        await foreach (var result in response.Value.GetResultsAsync(ct))
        {
            results.Add(new SearchResult
            {
                Text = result.Document.Text ?? string.Empty,
                Score = result.Score ?? 0f,
                DocumentId = result.Document.DocumentId ?? string.Empty,
                ChunkIndex = result.Document.ChunkIndex ?? 0
            });
        }

        return results;
    }
}

public sealed record DocumentChunkProjection(
    string Text,
    string DocumentId,
    int ChunkIndex);

public sealed record SearchResult(
    string Text,
    float Score,
    string DocumentId,
    int ChunkIndex);

